@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply

<section class="step-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = (string?)e.Value ?? string.Empty" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @(_isValidating ? "Validating..." : "Next")
        </button>
    </div>
</section>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _isValidating = true;
        var emailValid = await ApplicationService.ValidateEmailAsync(Email);
        _isValidating = false;

        if (!emailValid)
        {
            _emailError = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply

<section class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="@(index + 1)"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private async Task HandleNext()
    {
        _validationError = null;

        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            _validationError = "Each position requires at least a company name and job title.";
            return;
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply

<section class="step-panel">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="@References[index]"
                       Index="@(index + 1)"
                       CanRemove="@(References.Count > 1)"
                       OnRefChanged="r => UpdateRef(index, r)"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
