@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply

<section class="step-panel">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="@References[index]"
                       Index="@(index + 1)"
                       CanRemove="@(References.Count > 1)"
                       OnRefChanged="r => UpdateRef(index, r)"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void UpdateRef(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void RemoveRef(int index)
    {
        References.RemoveAt(index);
    }

    private void AddRef()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;

        if (References.Count < 2)
        {
            _validationError = "Please provide at least 2 references.";
            return;
        }

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            _validationError = "Each reference requires at least a name and email.";
            return;
        }

        await OnNext.InvokeAsync(References);
    }
