@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply

<section class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <textarea rows="12" class="cover-letter-input"
                  value="@CoverLetter"
                  @oninput="HandleInput"
                  maxlength="2000"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="char-count @(CoverLetter.Length > 1800 ? "warn" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = (string?)e.Value ?? string.Empty;
    }

    private async Task HandleNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _validationError = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}

