@page "/apply"
@rendermode InteractiveServer
@namespace sv_a31912572a544df0988eeb1dab1c36e3.Components.Pages.Apply
@using sv_a31912572a544df0988eeb1dab1c36e3.Models
@using sv_a31912572a544df0988eeb1dab1c36e3.Services

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_personal.FullName"
                              Email="@_personal.Email"
                              Phone="@_personal.Phone"
                              Address="@_personal.Address"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@_references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@_personal"
                        Work="@(new WorkHistory(_workEntries))"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    private PersonalInfo _personal = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> _workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> _references = new()
    {
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string _coverLetter = string.Empty;

    private void HandlePersonalNext(PersonalInfo info)
    {
        _personal = info;
        CompleteAndAdvance(0);
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        _workEntries = entries;
        CompleteAndAdvance(1);
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        _references = refs;
        CompleteAndAdvance(2);
    }

    private void HandleCoverLetterNext(string letter)
    {
        _coverLetter = letter;
        CompleteAndAdvance(3);
    }

    private void CompleteAndAdvance(int step)
    {
        _completedSteps.Add(step);
        _currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }
}

